		private static Task AckAuthenticate(INetworkClient client, uint value, byte[] sender = null, byte[] receiver = null)
		{
			var sender0 = sender ?? LoginWorldSender;
			var receiver0 = receiver ?? LoginWorldReceiver(client);

			return new PacketStream()
				.WriteHeader(sender0, receiver0, GameInterfaceDispatchOpcodes.DispatchAckAuthenticate)
				.WriteUInt32(value)
				.SendAsync(client);
		}
		// Receiver for the create-editor (clientInstance=0x021662C8) conversation family.
		// The create-editor 0x2000 receiver is built per session from the character's real instance id -
		// see CreateEditorReceiver(client) in GameServerListener. The editor/world bursts are constructed at
		// send time (Burst + SendBurst in PacketBurstHelper) with the same instance written into the header and
		// body, so auth replies and burst packets stay on one conversation.

		private async Task ApplySpell(INetworkClient client, uint applyTo, uint applyFrom, uint spellId, byte[] data = null)
		{
			// Use as 'dummy' data (comes from Scythe Shield Rank 3 (3 hours, 20 min, 28ish sec))
			var spellData = new byte[]
			{
				0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x13, 0x7E, 0x26, // 1277478
				0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, 0x38, 0x7E, // 145534
				0x00, 0x00, 0x00, 0x50, // 80
				0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x50, // 80
				0x00, 0x00, 0x00, 0x00, 0x14, 0xC5, 0xC9, 0x12 // 348506386
			};

			data ??= spellData;

			await new PacketStream()
				.WriteHeader(LoginWorldSender, LoginWorldReceiver(client), GameInterfaceDispatchOpcodes.DispatchPassBlob)
				.WriteArrayUInt32Length(s => s
					.WriteUInt32(GameServer0X2000RespondsOpcodes.ApplySpell)
					.WriteUInt32(EntityClass.Character)
					.WriteUInt32(applyTo) //Apply to ?
					.WriteUInt16(0x0000)
					.WriteUInt32(spellId) // SpellID
					.WriteUInt32(EntityClass.Character)
					.WriteUInt32(applyFrom) // apply from ?
					.WriteArray(data))
				.SendAsync(client);

			// Register a SELF-buff (applyTo == applyFrom) so the server tracks it (.buffs / CancelBuff / tick
			// expiry). Centralized here so EVERY ApplySpell send path registers - the mount buff, .spelltest, the
			// summon cast and the BCC cast path - not just the inbound cast handler (#69). Offensive casts
			// (applyTo != applyFrom) are damage, not buffs, and are handled by ResolveOffensiveCast.
			if (applyTo == applyFrom)
			{
				var entity = _simulation.PlayerWorldEntity(client);
				if (entity != null && entity.Handle == applyTo)
					entity.ActiveBuffs[spellId] = new World.ActiveBuff(spellId, applyFrom, DateTimeOffset.UtcNow, null);
			}
		}

		private static Task ReportDimensionId(INetworkClient client, uint realmId, byte[] sender = null, byte[] receiver = null)
		{
			var sender0 = sender ?? LoginWorldSender;
			var receiver0 = receiver ?? LoginWorldReceiver(client);

			return new PacketStream()
				.WriteHeader(sender0, receiver0, GameInterfaceDispatchOpcodes.DispatchReportDimesionID)
				.WriteString(realmId.ToString())
				.SendAsync(client);
		}

		private static Task ReportServerId(INetworkClient client, uint value, byte[] sender = null, byte[] receiver = null)
		{
			var sender0 = sender ?? LoginWorldSender;
			var receiver0 = receiver ?? LoginWorldReceiver(client);
			var packetData0 = new byte[] { 0x00, 0x00, 0x00, 0x54, 0x00, 0x00, 0x00, 0x01 };

			return new PacketStream()
				.WriteHeader(sender0, receiver0, GameInterfaceDispatchOpcodes.DispatchReportServerID)
				.WriteArray(packetData0)
				.SendAsync(client);
		}

		private static Task SendExistingCharacterPostReadyDataPacket(INetworkClient client, uint opcode, byte[] tail)
		{
			return new PacketStream()
				.WriteHeader(ExistingCharacterWorldEntryPromptSender, ConanEndpoints.EndpointBytes(ConanEndpoints.GameInterfaceType, client.Session.Account.ClientInstance), GameInterfaceDispatchOpcodes.DispatchPassBlob)
				.WriteArrayUInt32Length(s => s
					.WriteUInt32(opcode)
					.WriteUInt32(EntityClass.Character)
					.WriteUInt32(client.Session.Account.ClientInstance)
					.WriteArray(SubstitutePostReadyInstance(tail, client.Session.Account.ClientInstance)))
				.SendAsync(client);
		}

		private static async Task SendExistingCharacterPostReadyFollowUp(INetworkClient client)
		{
			await SendExistingCharacterPostReadyDataPacket(client, 0x06EC1255, ExistingCharacterPostReady06Ec1255Tail);
			await SendExistingCharacterPostReadyDataPacket(client, 0x864CFEF8, ExistingCharacterPostReady864CfeF8Tail);

			await new PacketStream()
				.WriteHeader(ExistingCharacterPostReadyReportServerIdSender, ConanEndpoints.EndpointBytes(ConanEndpoints.GameCharInterfaceProjectType, client.Session.Account.ClientInstance), GameInterfaceDispatchOpcodes.DispatchReportServerID)
				.WriteByte(0x01)
				.SendAsync(client);

			await SendExistingCharacterPostReadyDataPacket(client, 0xA36D3B74, ExistingCharacterPostReadyA36D3B74StartFixed3DTail);
			await SendExistingCharacterPostReadyDataPacket(client, 0xA36D3B74, ExistingCharacterPostReadyA36D3B74FelasTail);
			await SendExistingCharacterPostReadyDataPacket(client, 0xA36D3B74, ExistingCharacterPostReadyA36D3B74WelcomeTutorialTail);
		}

		private static Task SendPost205FOxf98E10B3Prompt(INetworkClient client)
		{
			return new PacketStream()
				.WriteHeader(ExistingCharacterWorldEntryPromptSender, ConanEndpoints.EndpointBytes(ConanEndpoints.GameInterfaceType, client.Session.Account.ClientInstance), GameInterfaceDispatchOpcodes.DispatchPassBlob)
				.WriteArrayUInt32Length(s => s
					.WriteUInt32(GameServer0X2000RespondsOpcodes.StatIIR)
					.WriteUInt32(EntityClass.Character)
					.WriteUInt32(client.Session.Account.ClientInstance)
					.WriteByte(0x01)
					.WriteUInt32(0x00000013)
					.WriteUInt32(0x00000000))
				.SendAsync(client);
		}

		private static Task SendPost205FSpawnCheck(INetworkClient client)
		{
			return new PacketStream()
